import{_ as i,a0 as u,w as p,s as o,I as s,x as a,a1 as l,A as e,ao as b}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Ubuntu 22.04 LTS 中安裝經典 GNOME Flashback 指南 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 22.04 LTS 中安裝經典 GNOME Flashback 指南 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 22.04 LTS 中安裝經典 GNOME Flashback 指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 22.04 LTS 中安裝經典 GNOME Flashback 指南 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220501 How to Install Classic GNOME Flashback in Ubuntu 22.04 LTS","title":"Ubuntu 22.04 LTS 中安裝經典 GNOME Flashback 指南","tag":"202205","desc":""},"relativePath":"202205/20220501 How to Install Classic GNOME Flashback in Ubuntu 22.04 LTS.md","filePath":"[post].md"}'),r={name:"202205/20220501 How to Install Classic GNOME Flashback in Ubuntu 22.04 LTS.md"};function d(h,t,g,m,k,M){const n=u("Link");return p(),o("div",null,[t[20]||(t[20]=s("h1",{id:"ubuntu-22-04-lts-中安裝經典-gnome-flashback-指南",tabindex:"-1"},[a("Ubuntu 22.04 LTS 中安裝經典 GNOME Flashback 指南 "),s("a",{class:"header-anchor",href:"#ubuntu-22-04-lts-中安裝經典-gnome-flashback-指南","aria-label":"Permalink to “Ubuntu 22.04 LTS 中安裝經典 GNOME Flashback 指南”"},"​")],-1)),t[21]||(t[21]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202205/23/151318xi8c3qipphg8xz0i.jpg",alt:""})],-1)),t[22]||(t[22]=s("blockquote",null,[s("p",null,"關於如何在最新的 UBUNTU 22.04 LTS 中安裝舊的經典 GNOME Flashback 的快速指南。")],-1)),s("p",null,[l(n,{href:"https://wiki.archlinux.org/index.php/GNOME/Flashback"},{default:e(()=>[...t[0]||(t[0]=[a("GNOME Flashback",-1)])]),_:1}),t[1]||(t[1]=a("（又名 classic GNOME）是舊 GNOME 3 shell 的一個分支，它使用早期 GNOME 2 技術的佈局和原則。它的速度快如閃電，並且在設計上非常輕量級。因此，它非常適合幾十年前的老舊硬件。",-1))]),s("p",null,[t[3]||(t[3]=a("隨着帶有現代 GNOME 42 的 ",-1)),l(n,{href:"https://www.debugpoint.com/2022/01/ubuntu-22-04-lts/"},{default:e(()=>[...t[2]||(t[2]=[a("Ubuntu 22.04 LTS",-1)])]),_:1}),t[4]||(t[4]=a(" 的發佈，有必要尋找輕量級的桌面環境選項。",-1))]),t[23]||(t[23]=b(`<p>此外，GNOME Flashback 很容易安裝在現代 Ubuntu Linux 中，你仍然可以享受 Ubuntu 性能而不必關心 GNOME 42、GTK4、libadwaita 之類的東西。</p><h3 id="在-ubuntu-22-04-lts-中下載並安裝經典-gnome-flashback" tabindex="-1">在 Ubuntu 22.04 LTS 中下載並安裝經典 GNOME Flashback <a class="header-anchor" href="#在-ubuntu-22-04-lts-中下載並安裝經典-gnome-flashback" aria-label="Permalink to “在 Ubuntu 22.04 LTS 中下載並安裝經典 GNOME Flashback”">​</a></h3><p>按照以下步驟在 Ubuntu 22.04 LTS 中下載並安裝經典 GNOME Flashback（Metacity）。</p><p>在 Ubuntu 22.04 LTS 中打開終端（CTRL+ALT+T）並運行以下命令。安裝大小約為 61MB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install gnome-session-flashback</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/05/Install-GNOME-Classic-Flashback-Metacity-in-Ubuntu-22.04-LTS.jpg" alt="Install GNOME Classic Flashback Metacity in Ubuntu 22.04 LTS"></p><p>最後，安裝完成後，退出。重新登錄時，在登錄選項中使用經典的 GNOME Flashback（Metacity） 。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/05/Choose-GNOME-Classic-while-loggin-in.jpg" alt="Choose GNOME Classic while logging in"></p><h3 id="經典-gnome-flashback-的特點" tabindex="-1">經典 GNOME Flashback 的特點 <a class="header-anchor" href="#經典-gnome-flashback-的特點" aria-label="Permalink to “經典 GNOME Flashback 的特點”">​</a></h3><p>首先，當你登錄時，你將體驗到傳統的 GNOME 技術，它已被證明具有良好的生產力，並且比今天的技術快得多。</p><p>在頂部有舊版的面板，左側是應用菜單，而系統托盤位於桌面的右上方。應用程序菜單顯示所有已安裝的應用和軟件快捷方式，你可以在工作流程中輕鬆瀏覽。</p><p>此外，在右側部分，系統托盤具有默認小部件，例如網絡、音量控制、日期和時間以及關機菜單。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/05/Classic-GNOME-Flashback-Metacity-in-Ubuntu-22.04-LTS.jpg" alt="Classic GNOME Flashback Metacity in Ubuntu 22.04 LTS"></p><p>底部面板包含打開的窗口和工作區切換器的應用列表。默認情況下，它為你提供四個工作區供你使用。</p><p>此外，你可以隨時更改頂部面板的設置以自動隱藏、調整面板大小和背景顏色。</p><p>除此之外，你可以通過 <code>ALT + 右鍵點擊</code> 頂部面板添加任意數量的舊版小程序。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/04/Panel-Context-Menu.png" alt="Panel Context Menu"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/04/Add-to-panel-widgets.png" alt="Add to panel widgets"></p><h3 id="經典-gnome-的性能" tabindex="-1">經典 GNOME 的性能 <a class="header-anchor" href="#經典-gnome-的性能" aria-label="Permalink to “經典 GNOME 的性能”">​</a></h3><p>首先，磁盤空間佔用極小，僅安裝 61 MB。我的測試使用了大約 28% 的內存，其中大部分被其他進程佔用。猜猜是誰？是的，是 snap-store（又名 Ubuntu 軟件）。</p><p>因此，總體而言，它非常輕巧，內存（僅 28 MB）和 CPU（0.1%）佔用空間非常小。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/05/Performance-of-GNOME-Classic-in-Ubuntu-22.04.jpg" alt="Performance of GNOME Classic in Ubuntu 22.04"></p><p>此外，假設你將其與同樣使用相同技術的 Ubuntu MATE 進行比較。在這種情況下，它比 MATE 更輕量，因為你不需要任何額外的 MATE 應用及其用於通知、主題和其他附加資源的軟件包。</p><h3 id="結束語" tabindex="-1">結束語 <a class="header-anchor" href="#結束語" aria-label="Permalink to “結束語”">​</a></h3><p>我希望本指南在你決定在 Ubuntu 22.04 LTS Jammy Jellyfish 中安裝經典 GNOME 之前幫助你獲得必要的信息。</p><hr>`,26)),s("p",null,[t[6]||(t[6]=a("via: ",-1)),l(n,{href:"https://www.debugpoint.com/2022/05/gnome-classic-ubuntu-22-04/"},{default:e(()=>[...t[5]||(t[5]=[a("https://www.debugpoint.com/2022/05/gnome-classic-ubuntu-22-04/",-1)])]),_:1})]),s("p",null,[t[11]||(t[11]=a("作者：",-1)),l(n,{href:"https://www.debugpoint.com/author/admin1/"},{default:e(()=>[...t[7]||(t[7]=[a("Arindam",-1)])]),_:1}),t[12]||(t[12]=a(" 選題：",-1)),l(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[8]||(t[8]=[a("lujun9972",-1)])]),_:1}),t[13]||(t[13]=a(" 譯者：",-1)),l(n,{href:"https://github.com/geekpi"},{default:e(()=>[...t[9]||(t[9]=[a("geekpi",-1)])]),_:1}),t[14]||(t[14]=a(" 校對：",-1)),l(n,{href:"https://github.com/turbokernel"},{default:e(()=>[...t[10]||(t[10]=[a("turbokernel",-1)])]),_:1})]),s("p",null,[t[17]||(t[17]=a("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[15]||(t[15]=[a("LCTT",-1)])]),_:1}),t[18]||(t[18]=a(" 原創編譯，",-1)),l(n,{href:"https://linux.cn/"},{default:e(()=>[...t[16]||(t[16]=[a("Linux中國",-1)])]),_:1}),t[19]||(t[19]=a(" 榮譽推出",-1))])])}const N=i(r,[["render",d]]);export{f as __pageData,N as default};
